import React from 'react';
import { Navigate, Route, Routes } from 'react-router-dom';
import LeaveDashboard from './LeaveDashboard';
import AppShell from './AppShell';
import ProtectedRoute from './ProtectedRoute';
import { ROLES } from '../navigation';

const AccessDenied = () => <main className="page-state"><h1>403</h1><p>You do not have permission to view this page.</p></main>;
const RoutePage = ({ title }) => <main className="page-state"><h1>{title}</h1><p>This workspace is ready for the {title.toLowerCase()} workflow.</p></main>;

const ShellRoute = ({ currentUser, onLogout, children }) => (
  <AppShell currentUser={currentUser} onLogout={onLogout}>
    {children}
  </AppShell>
);

const AuthenticatedRoutes = ({ currentUser, onUserUpdated, handleLogout }) => (
  <Routes>
    <Route path="/403" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><AccessDenied /></ShellRoute>} />
    <Route element={<ProtectedRoute currentUser={currentUser} />}>
      <Route path="/dashboard" element={<LeaveDashboard currentUser={currentUser} onUserUpdated={onUserUpdated} handleLogout={handleLogout} />} />
      <Route path="/leave/apply" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Apply Leave" /></ShellRoute>} />
      <Route path="/leave/my" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="My Leave" /></ShellRoute>} />
      <Route path="/leave/history" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="History" /></ShellRoute>} />
      <Route path="/delegations" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Delegations" /></ShellRoute>} />
      <Route path="/chat" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Chat" /></ShellRoute>} />
      <Route element={<ProtectedRoute currentUser={currentUser} requiredRoles={[ROLES.MANAGER, ROLES.HR]} />}>
        <Route path="/team/approvals" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Approvals" /></ShellRoute>} />
        <Route path="/team/calendar" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Team Calendar" /></ShellRoute>} />
        <Route path="/team/reports" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Reports" /></ShellRoute>} />
      </Route>
      <Route element={<ProtectedRoute currentUser={currentUser} requiredRoles={[ROLES.HR]} />}>
        <Route path="/hr" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="HR Module" /></ShellRoute>} />
        <Route path="/hr/verification" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="HR Verification" /></ShellRoute>} />
        <Route path="/hr/compliance" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Compliance" /></ShellRoute>} />
        <Route path="/hr/users" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Users" /></ShellRoute>} />
        <Route path="/hr/leave-types" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Leave Types" /></ShellRoute>} />
        <Route path="/hr/departments" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Departments" /></ShellRoute>} />
        <Route path="/hr/audit-log" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Audit Log" /></ShellRoute>} />
      </Route>
      <Route path="/settings" element={<ShellRoute currentUser={currentUser} onLogout={handleLogout}><RoutePage title="Settings" /></ShellRoute>} />
      <Route path="*" element={<Navigate to="/dashboard" replace />} />
    </Route>
  </Routes>
);

export default AuthenticatedRoutes;
